entries[135594] = { ["name"] = "Blitzbombe", ["text"] = "40 Meter Reichweite\nSofort 11 sek. Abklingzeit\nWirft eine elektrisch aufgeladene Bombe auf den Zielort. Die Bombe verströmt Elektrizität und fügt allen Gegnern in der Nähe alle 1 Sek. Schaden zu.\n\nEs kann immer nur eine Blitzbombe gleichzeitig aktiv sein." }
entries[135595] = { ["name"] = "Fluss der Schmerzen" }
entries[135596] = { ["name"] = "Statische Überladung", ["text"] = "40 Meter Reichweite\nSofort\nVerursacht eine statische Überladung an der Position der Blitzbombe, fügt Gegnern in der Nähe massiven Schaden zu und betäubt sie.\n\nDiese Elektrizitätsüberladung deaktiviert die Blitzbombe." }
entries[135597] = { ["name"] = "Mit Klauen und Zähnen", ["text"] = "100 Meter Reichweite\nSofort\nEure automatischen Angriffe in Bärengestalt haben eine Chance von 40%, Euren nächsten Einsatz von 'Zermalmen' innerhalb von 10 Sek. zu verstärken. So verstärkte Anwendungen von 'Zermalmen' verringern den Schaden des nächsten automatischen Angriffs des Ziels innerhalb von 15 Sek. um [Max((Angriffskraft - 2 * Beweglichkeit) * 2.2, Ausdauer * 250 / 100) * 0.4]." }
entries[135598] = { ["name"] = "Stage 2 - Boss Emote" }
entries[135599] = { ["name"] = "Tragbare Landmine", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Wiederaufladung\n5 Aufladungen\nPlatziert eine Landmine am Zielort. Gegnerische Ziele, die in die Fallen laufen fügen Gegnern in der Nähe Schaden zu und betäuben sie kurzzeitig." }
entries[135600] = { ["name"] = "Detonation", ["text"] = "40 Meter Reichweite\nSofort\nDie Landmine explodiert, fügt Gegnern in der Nähe Schaden zu und betäubt sie." }
entries[135601] = { ["name"] = "Mit Klauen und Zähnen", ["text"] = "100 Meter Reichweite\nSofort\nDisziplin ( Hotfix - Passivfähigkeit )\nEure automatischen Angriffe in Bärengestalt haben eine Chance von 40%, Euren nächsten Einsatz von 'Zermalmen' innerhalb von 10 Sek. zu verstärken. So verstärkte Anwendungen von 'Zermalmen' verringern den Schaden des nächsten automatischen Angriffs des Ziels innerhalb von 15 Sek. um [Max((Angriffskraft - 2 * Beweglichkeit) * 2.2, Ausdauer * 250 / 100) * 0.4].\n\nHeilig, Schattenkämpfer\nEure automatischen Angriffe in Bärengestalt haben eine Chance von 40%, Euren nächsten Einsatz von 'Zermalmen' innerhalb von 10 Sek. zu verstärken. So verstärkte Anwendungen von 'Zermalmen' verringern den Schaden des nächsten automatischen Angriffs des Ziels innerhalb von 15 Sek. um [Max((Angriffskraft - 2 * Beweglichkeit) * 2.2, Ausdauer * 250 / 100) * 0.4]." }
