entries[135605] = { ["name"] = "Schaf detonieren", ["text"] = "150 Meter Reichweite\nSofort 12 sek. Abklingzeit\nDetoniert den Sprengstoff in allen aufgestellten Schafen innerhalb von 70 Metern.\n\nDetonierende Schafe fügen allen Gegnern in der Nähe Schaden zu." }
entries[135606] = { ["name"] = "Seelenschatten", ["text"] = "Sofort\nAls letzte Verzweiflungstat greift die rachsüchtige Seele alle Gegner in der Nähe an und fügt ihnen im Verlauf von 8 Sek. alle 2 Sek. 12500 Schattenschaden zu." }
entries[135607] = { ["name"] = "Unsterbliche Geheimnisse", ["text"] = "Sofort\nAls letzte Verzweiflungstat entfesselt der Geist der Korun seine verbleibende Geisterenergie gegen alle Gegner in der Nähe, fügt ihnen 14250 bis 15750 Schattenschaden zu und erhöht den verursachten Schaden um 5%." }
