entries[135612] = { ["name"] = "Feuer spucken", ["text"] = "Kanalisiert (Wirken in 4 sek.) 5 sek. Abklingzeit\nZiele in einem kegelförmigen Bereich vor dem Zaubernden erleiden 4 Sek. lang Feuerschaden." }
