entries[135614] = { ["name"] = "Flammen schüren", ["text"] = "20 Meter Reichweite\nWirken in 1.25 sek. 1 sek. Abklingzeit\nVerursacht Feuerschaden bei einem Feind und erhöht 15 Sek. lang seinen erlittenen Feuerschaden." }
entries[135615] = { ["name"] = "Pierre", ["text"] = "Wirken in 2 sek. 5 min Abklingzeit\nBaut ein Lagerfeuer auf, das die Willenskraft von jedem in der Nähe um 4 erhöht und das Kochen ermöglicht." }
entries[135616] = { ["name"] = "Artillerieschuss", ["text"] = "Sofort\nFügt Gegnern im Umkreis von 6 Metern Feuerschaden zu und betäubt sie 1 Sek. lang." }
entries[135617] = { ["name"] = "Sturmangriffsschwung", ["text"] = "Sofort\nErhöht den verursachten Schaden um 10%. Fügt einen Stapel hinzu, wenn der Zaubernde einen Gegner anstürmt, bis zu einem Maximum von 20 Stapeln." }
entries[135619] = { ["name"] = "Siegreicher Stoß", ["text"] = "Nahkampfreichweite\nWirken in 3 sek.\nEin mächtiger Angriff, der allen Gegnern im Umkreis von 8 Metern 450% Waffenschaden zufügt und ihre Chance, zu verfehlen, um 50% erhöht." }
entries[135620] = { ["name"] = "Schildhieb", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nSchlägt mit dem Schild des Zaubernden auf einen Feind ein, verursacht 10% Waffenschaden und unterbricht den gewirkten Zauber." }
entries[135621] = { ["name"] = "Statische Aufladung", ["text"] = "Wirken in 5 sek.\nBetäubt Gegner im Umkreis von 8 Metern 5 Sek. lang." }
entries[135622] = { ["name"] = "Totem der Energiespeicherung", ["text"] = "35 Meter Reichweite\nWirken in 2 sek.\nBeschwört ein Lufttotem mit 5 Gesundheit zu den Füßen des Zaubernden, das nach 6 Sek. explodiert und alle Gegner im Umkreis von 8 Metern 5 Sek. lang betäubt." }
entries[135623] = { ["name"] = "Kampfrausch", ["text"] = "Wirken in 3 sek.\nErhöht Nahkampf-, Distanzangriffs- und Zaubertempo aller in der Nähe befindlichen Verbündeten 20 Sek. lang um 35%." }
entries[135624] = { ["name"] = "Kettenheilung", ["text"] = "150 Mana 40 Meter Reichweite\nWirken in 5 sek.\nErfüllt einen verwundeten Verbündeten mit Heilenergie, die sich auf einen anderen in der Nähe befindlichen Verbündeten ausbreitet. Der Zauber wirkt sich auf bis zu 3 Ziele aus, aber die Heilenergie wird bei jedem folgenden Ziel um 50% reduziert." }
entries[135625] = { ["name"] = "Große Verhexung", ["text"] = "Sofort\nVerwandelt in der Nähe befindliche Feinde in Frösche, sodass sie 8 Sek. lang weder angreifen noch Zauber wirken können." }
entries[135626] = { ["name"] = "Große Verhexung", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nBeginnt, 'Große Verhexung' zu kanalisieren, verwandelt alle Gegner im Umkreis von 0 Metern in Frösche. Immun gegen Betäubungs- und Kontrollverlusteffekte während des Zauberwirkens." }
